const EQUIP_ALIAS: Record<string, string[]> = {
  barbell: ["barbell"],
  dumbbell: ["dumbbell", "dumbbells"],
  dumbbells: ["dumbbell", "dumbbells"],
  kettlebell: ["kettlebells"],
  kettlebells: ["kettlebells"],
  machine: ["machine"],
  cable: ["cable", "cables"],
  bands: ["bands", "resistance bands"],
  bodyweight: ["bodyweight"],
  "body only": ["bodyweight"],
};

/**
 * Filter the catalog to what the athlete actually has (bodyweight always
 * allowed). Returns the items (capped) so callers can build both the prompt
 * text and the allowed-slug set from one source.
 */
export function filterCatalog(equipment: string[] | null | undefined, cap = 180): CatalogItem[] {
  const have = new Set<string>(["bodyweight"]);
  for (const raw of equipment ?? []) {
    const key = String(raw).toLowerCase().trim();
    (EQUIP_ALIAS[key] ?? [key]).forEach((v) => have.add(v));
  }
  // If the athlete listed no equipment, assume a full gym (don't starve the plan).
  const fullGym = !equipment || equipment.length === 0;
  const items = EXERCISE_CATALOG.filter((e) => fullGym || have.has(e.equipment));
  return (items.length ? items : EXERCISE_CATALOG).slice(0, cap);
}

/** Compact catalog list for the prompt: `slug | name | equipment | primary`. */
export function buildCatalogPrompt(equipment: string[] | null | undefined, cap = 180): string {
  return filterCatalog(equipment, cap)
    .map((e) => `- ${e.slug} | ${e.name} | ${e.equipment} | ${e.primary}`)
    .join("\n");
}
